<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { useI18n } from 'vue-i18n'
import { ElMessage } from 'element-plus'
import UserCenterCard from '@/components/users/UserCenterCard.vue'
import { getRiskDashboard, type RiskDetail } from '@/api/adminRisk'
import { selectedTimeToBackend } from '@/utils/timezone'

type Point={name:string;value:number}
const {t}=useI18n(),loading=ref(false),data=ref<RiskDetail>({}),period=ref('7D'),custom=reactive<string[]>([])
const metricKeys=['pendingReviews','highRiskUsers','criticalEvents','blockedAccounts','blockedDevices','blockedIPs','suspiciousWithdrawals','bonusAbuse','callbackAnomalies']
const chartKeys=['eventsByDay','eventsByType','eventsByLevel','reviewResults','topCountries','topIPs','topDevices']
const metrics=computed(()=>data.value.metrics&&typeof data.value.metrics==='object'?data.value.metrics as Record<string,number>:{})
function range(){const now=new Date(),from=new Date(now);if(period.value==='TODAY')from.setHours(0,0,0,0);else if(period.value==='YESTERDAY'){from.setDate(from.getDate()-1);from.setHours(0,0,0,0);now.setDate(now.getDate()-1);now.setHours(23,59,59,999)}else if(period.value==='30D')from.setDate(from.getDate()-29);else if(period.value==='CUSTOM'&&custom.length===2)return{from:selectedTimeToBackend(custom[0]),to:selectedTimeToBackend(custom[1],true)};else from.setDate(from.getDate()-6);return{from:from.toISOString(),to:now.toISOString()}}
async function load(){loading.value=true;try{data.value=await getRiskDashboard(range())}catch(e){ElMessage.error(e instanceof Error?e.message:t('riskCenter.messages.loadFailed'))}finally{loading.value=false}}
function points(key:string):Point[]{const value=data.value[key];return Array.isArray(value)?value.map(v=>({name:String((v as Point).name||'-'),value:Number((v as Point).value||0)})):[]}
function max(key:string){return Math.max(1,...points(key).map(p=>p.value))}
onMounted(load)
</script>
<template><div v-loading="loading" class="risk-dashboard"><UserCenterCard :title="t('riskCenter.dashboard.title')"><div class="period"><el-radio-group v-model="period" @change="load"><el-radio-button value="TODAY">{{t('riskCenter.period.today')}}</el-radio-button><el-radio-button value="YESTERDAY">{{t('riskCenter.period.yesterday')}}</el-radio-button><el-radio-button value="7D">{{t('riskCenter.period.sevenDays')}}</el-radio-button><el-radio-button value="30D">{{t('riskCenter.period.thirtyDays')}}</el-radio-button><el-radio-button value="CUSTOM">{{t('riskCenter.period.custom')}}</el-radio-button></el-radio-group><el-date-picker v-if="period==='CUSTOM'" v-model="custom" type="daterange" value-format="YYYY-MM-DD" @change="load"/></div></UserCenterCard><div class="metrics"><div v-for="key in metricKeys" :key="key" class="metric"><span>{{t(`riskCenter.metrics.${key}`)}}</span><strong>{{metrics[key]||0}}</strong></div></div><div class="charts"><UserCenterCard v-for="key in chartKeys" :key="key" :title="t(`riskCenter.charts.${key}`)"><div v-if="points(key).length" class="bars"><div v-for="p in points(key)" :key="p.name" class="bar"><span class="bar__label">{{p.name}}</span><div class="bar__track"><i :style="{width:`${Math.max(3,p.value/max(key)*100)}%`}"/></div><b>{{p.value}}</b></div></div><el-empty v-else :description="t('riskCenter.messages.empty')"/></UserCenterCard></div></div></template>
<style scoped>.risk-dashboard{display:grid;gap:16px}.period{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap}.metrics{display:grid;grid-template-columns:repeat(3,minmax(180px,1fr));gap:14px}.metric{padding:18px 20px;border:1px solid #ebeef5;border-radius:6px;background:#fff;display:flex;align-items:center;justify-content:space-between}.metric span{color:#606266}.metric strong{font-size:25px;color:#303133}.charts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.bars{display:grid;gap:12px}.bar{display:grid;grid-template-columns:130px 1fr 44px;gap:10px;align-items:center}.bar__label{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.bar__track{height:10px;background:#edf1f7;border-radius:2px;overflow:hidden}.bar__track i{display:block;height:100%;background:#409eff}.bar b{text-align:right}@media(max-width:900px){.metrics{grid-template-columns:repeat(2,1fr)}.charts{grid-template-columns:1fr}}@media(max-width:560px){.metrics{grid-template-columns:1fr}}</style>
